# owner: platform
import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def make(worker, day, begin, finish):
    return Shift(worker, day, Span(begin * 60, finish * 60))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            make("Bea", "mon", 9, 12),
            make("Al", "mon", 9, 17),
            make("Bea", "tue", 9, 13)
        ])
        self.assertIn("Al: 1 shifts, 8.0", lines[0])
        self.assertIn("Bea: 2 shifts, 7.0", lines[1])

    def test_rounds_to_one_decimal(self):
        shift = Shift("Cy", "wed", Span(540, 580))
        self.assertEqual(
            timesheet_lines([shift]),
            ["Cy: 1 shifts, 0.7 hours"]
        )

    def test_ties_sorted_by_name(self):
        lines = timesheet_lines([
            make("Zed", "mon", 9, 10),
            make("Amy", "mon", 9, 10)
        ])
        self.assertTrue(lines[0].startswith("Amy"))

    def test_empty_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            shift = make(name, "mon", 9, 10)
            with self.assertRaises(ProjectError):
                timesheet_lines([shift])
